.activity-filters {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  gap: var(--space-9);
  margin-bottom: var(--space-6);
  padding: var(--space-6);
  background: var(--surface-panel);
  border: var(--border-width-hairline) solid var(--border-subtle);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-1);
  color: var(--text-primary);
}

.activity-filters[hidden] {
  display: none;
}

.filter-field {
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
}

.filter-field label,
.filter-types legend {
  font: var(--type-label);
}

.filter-types {
  flex: 1;
  margin: var(--space-0);
  padding: var(--space-0);
  border: none;
}

.filter-types legend {
  padding: var(--space-0);
  margin-bottom: var(--space-4);
}

.filter-options {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2) var(--space-7);
}

.filter-options label {
  display: flex;
  align-items: center;
  gap: var(--space-4);
  min-height: var(--space-8);
  font: var(--type-body);
  cursor: pointer;
}

.filter-options input {
  margin: var(--space-0);
  accent-color: var(--accent-fill);
}

.filter-actions {
  display: flex;
  gap: var(--space-4);
  margin-top: var(--space-5);
}

.activity-filters select,
.activity-filters button {
  font: var(--type-label);
  padding: var(--space-2) var(--space-5);
  background: var(--surface-panel);
  color: var(--text-primary);
  border: var(--border-width-hairline) solid var(--border-default);
  border-radius: var(--radius-md);
  transition: border-color var(--duration-fast) var(--ease-standard),
    background-color var(--duration-fast) var(--ease-standard);
}

.activity-filters select {
  padding: var(--space-4) var(--space-5);
}

.activity-filters button {
  cursor: pointer;
}

.activity-filters select:hover,
.activity-filters button:hover {
  border-color: var(--border-strong);
}

.activity-filters button:hover {
  background: var(--surface-hover);
}

.activity-filters :focus-visible {
  outline: var(--border-width-thick) solid var(--border-focus);
  outline-offset: var(--border-width-thick);
}

@media (prefers-reduced-motion: reduce) {
  .activity-filters select,
  .activity-filters button {
    transition: none;
  }
}

.activity-count {
  font: var(--type-body-sm);
  color: var(--text-secondary);
}

.activity-no-match {
  color: var(--text-secondary);
}
EOF
