// Throwaway: drives Chrome over CDP with real mouse/keyboard input.
const [, , wsUrl] = process.argv;
const ws = new WebSocket(wsUrl);
let id = 0; const pending = new Map();
ws.onmessage = (m) => { const d = JSON.parse(m.data); if (pending.has(d.id)) { pending.get(d.id)(d); pending.delete(d.id); } };
const send = (method, params = {}) => new Promise((r) => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
const ev = async (expr) => (await send('Runtime.evaluate', { expression: expr, returnByValue: true })).result.result.value;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
async function click(sel) {
  const box = await ev(`(() => { const r = document.querySelector(${JSON.stringify(sel)}).getBoundingClientRect(); return [r.x + r.width/2, r.y + r.height/2]; })()`);
  for (const type of ['mousePressed', 'mouseReleased']) await send('Input.dispatchMouseEvent', { type, x: box[0], y: box[1], button: 'left', clickCount: 1 });
  await sleep(100);
}
async function key(k, code, keyCode, extra = {}) {
  await send('Input.dispatchKeyEvent', { type: 'rawKeyDown', key: k, code, windowsVirtualKeyCode: keyCode, ...extra });
  await send('Input.dispatchKeyEvent', { type: 'keyUp', key: k, code, windowsVirtualKeyCode: keyCode, ...extra });
  await sleep(100);
}
const state = () => ev(`({count: document.querySelector('#activity-count').textContent, rows: document.querySelectorAll('#activity-table tbody tr').length, types: [...new Set([...document.querySelectorAll('#activity-table tbody tr')].map(r => r.children[1]?.textContent))].join(', '), noMatch: !!document.querySelector('.activity-no-match')})`);
const shot = async (name) => { const { result } = await send('Page.captureScreenshot', { captureBeyondViewport: true }); (await import('node:fs')).writeFileSync(`/tmp/actcheck/${name}.png`, Buffer.from(result.data, 'base64')); };
ws.onopen = async () => {
  await send('Emulation.setDeviceMetricsOverride', { width: 1200, height: 900, deviceScaleFactor: 1, mobile: false });
  await send('Page.reload'); await sleep(800);
  console.log('UA:', await ev('navigator.userAgent'));
  console.log('panel visible:', await ev(`!document.querySelector('#activity-filters').hidden`));
  console.log('load:', JSON.stringify(await state())); await shot('1-load');
  await click('#filter-clear-all'); console.log('clear all:', JSON.stringify(await state()));
  await click('input[value="Sign-in failed"]'); console.log('tick Sign-in failed:', JSON.stringify(await state())); await shot('2-failed');
  await click('input[value="Password changed"]'); console.log('also Password changed:', JSON.stringify(await state()));
  for (const v of ['30', '7', '1', '90']) { await ev(`document.querySelector('#filter-range').focus()`); await ev(`(() => { const s = document.querySelector('#filter-range'); s.value = '${v}'; s.dispatchEvent(new Event('change', {bubbles: true})); })()`); console.log(`range ${v}d:`, JSON.stringify(await state())); if (v === '1') await shot('3-nomatch'); }
  await click('#filter-select-all'); console.log('select all:', JSON.stringify(await state()));
  await ev('document.activeElement.blur(); document.body.focus()');
  const order = [];
  for (let i = 0; i < 13; i++) { await key('Tab', 'Tab', 9); order.push(await ev(`(() => { const a = document.activeElement; return (a.id || a.value || a.tagName) + ' outline=' + getComputedStyle(a).outlineStyle + ' ' + getComputedStyle(a).outlineWidth + ' ' + getComputedStyle(a).outlineColor; })()`)); }
  console.log('tab order:\n  ' + order.join('\n  '));
  await key(' ', 'Space', 32); console.log('Space on focused item:', JSON.stringify(await state())); await shot('4-keyboard');
  await key('Enter', 'Enter', 13); console.log('URL after Enter:', await ev('location.href.split("/").pop()'));
  await send('Emulation.setDeviceMetricsOverride', { width: 320, height: 800, deviceScaleFactor: 1, mobile: true });
  await sleep(300); console.log('320px filters overflow:', await ev(`document.querySelector('#activity-filters').scrollWidth > document.querySelector('#activity-filters').clientWidth`)); await shot('5-320');
  process.exit(0);
};
EOF
CHROME="/Applications/Google Chrome.app/Contents/MacOS/Google Chrome"
"$CHROME" --headless=new --remote-debugging-port=9333 --user-data-dir=/tmp/actcheck/profile --no-first-run "file://$PWD/activity.html" >/tmp/actcheck/chrome.log 2>&1 &
sleep 3
WS=$(curl -s localhost:9333/json | python3 -c 'import json,sys; print([p for p in json.load(sys.stdin) if p["type"]=="page"][0]["webSocketDebuggerUrl"])')
node /tmp/actcheck/drive.mjs "$WS"; date -u

